BEGIN;
SELECT no_plan();

INSERT INTO auth.users(id,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,aud,role,created_at,updated_at) VALUES ('f1010000-0000-4000-8000-000000000001','f1-admin@example.test','hash',now(),'{}','{}','authenticated','authenticated',now(),now());
INSERT INTO platform_core.tenants(id,display_name,created_by_operator_id) VALUES ('f1020000-0000-4000-8000-000000000001','F1 isolated repro','f1010000-0000-4000-8000-000000000001');
INSERT INTO platform_core.tenant_roles(tenant_id,role_id,role_key,role_version,permission_snapshot,protects_tenant_admin) VALUES ('f1020000-0000-4000-8000-000000000001','f1030000-0000-4000-8000-000000000001','f1.operator',1,ARRAY['people.view','people.manage','employment.manage','org_context.manage','compensation.view','compensation.manage','attendance.view','attendance.manage','attendance.correct','attendance.approve'],'false');
INSERT INTO platform_core.tenant_memberships(tenant_id,user_id,access_state,created_by_operator_id) VALUES ('f1020000-0000-4000-8000-000000000001','f1010000-0000-4000-8000-000000000001','active','f1010000-0000-4000-8000-000000000001');
INSERT INTO platform_core.membership_roles(tenant_id,user_id,role_id) VALUES ('f1020000-0000-4000-8000-000000000001','f1010000-0000-4000-8000-000000000001','f1030000-0000-4000-8000-000000000001');
INSERT INTO platform_core.tenant_capability_entitlements(tenant_id,capability_key,is_granted,valid_from,actor_user_id,reason) VALUES ('f1020000-0000-4000-8000-000000000001','hr.people',true,now()-interval '1 minute','f1010000-0000-4000-8000-000000000001','F1 rollback repro'),('f1020000-0000-4000-8000-000000000001','hr.attendance',true,now()-interval '1 minute','f1010000-0000-4000-8000-000000000001','F1 rollback repro');
INSERT INTO platform_core.tenant_legal_entities(tenant_id,id,display_name,is_default) VALUES ('f1020000-0000-4000-8000-000000000001','f1040000-0000-4000-8000-000000000001','F1 Employer',true);
INSERT INTO platform_core.tenant_sites(tenant_id,id,legal_entity_id,display_name,is_default,is_active) VALUES ('f1020000-0000-4000-8000-000000000001','f1050000-0000-4000-8000-000000000001','f1040000-0000-4000-8000-000000000001','F1 Main',true,true);
INSERT INTO time.work_policy_templates(tenant_id,id,code,is_active,head_version) VALUES ('f1020000-0000-4000-8000-000000000001','f1060000-0000-4000-8000-000000000001','F1-FLEX',true,1);
INSERT INTO time.work_policy_versions(tenant_id,template_id,version,name,schedule_kind,timezone_name,work_days,required_minutes,earliest_punch,latest_punch,created_by) VALUES ('f1020000-0000-4000-8000-000000000001','f1060000-0000-4000-8000-000000000001',1,'F1 Flexible','flexible','Africa/Cairo',ARRAY[1,2,3,4,5,6,7]::smallint[],60,'00:00','23:59','f1010000-0000-4000-8000-000000000001');
INSERT INTO time.work_policy_versions(tenant_id,template_id,version,name,schedule_kind,timezone_name,work_days,required_minutes,earliest_punch,latest_punch,created_by)
SELECT tenant_id,template_id,2,'F1 New version','flexible',timezone_name,work_days,120,earliest_punch,latest_punch,created_by FROM time.work_policy_versions WHERE template_id='f1060000-0000-4000-8000-000000000001' AND version=1;
UPDATE time.work_policy_templates SET head_version=2 WHERE id='f1060000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f1010000-0000-4000-8000-000000000001',true);
SELECT set_config('f1.employee',public.create_people_employee('f1020000-0000-4000-8000-000000000001','F1-TRANSFER','F1 Transfer Employee','f1040000-0000-4000-8000-000000000001','f1050000-0000-4000-8000-000000000001',(now() AT TIME ZONE 'Africa/Cairo')::date-10,'monthly',1000,true)::text,true);
SELECT set_config('f1.employment',(current_setting('f1.employee')::jsonb->>'employment_id'),true);
RESET ROLE;
UPDATE people.work_assignments SET work_policy_template_id='f1060000-0000-4000-8000-000000000001',work_policy_version=1 WHERE tenant_id='f1020000-0000-4000-8000-000000000001' AND employment_id=current_setting('f1.employment')::uuid;
SELECT set_config('f1.yesterday',((now() AT TIME ZONE 'Africa/Cairo')::date-1)::text,true);
SELECT set_config('f1.today',(now() AT TIME ZONE 'Africa/Cairo')::date::text,true);
SET LOCAL ROLE authenticated;
SELECT set_config('f1.open_before',public.attendance_open_day('f1020000-0000-4000-8000-000000000001',current_setting('f1.yesterday')::date,NULL,50)::text,true);
SELECT set_config('request.jwt.claim.sub','f1010000-0000-4000-8000-000000000001',true);
SELECT public.schedule_people_work_assignment('f1020000-0000-4000-8000-000000000001',current_setting('f1.employment')::uuid,current_setting('f1.today')::date,'f1050000-0000-4000-8000-000000000001',NULL,NULL,NULL);
RESET ROLE;
SELECT is((SELECT work_policy_template_id FROM people.work_assignments WHERE tenant_id='f1020000-0000-4000-8000-000000000001' AND employment_id=current_setting('f1.employment')::uuid AND valid_from=current_setting('f1.today')::date),
 'f1060000-0000-4000-8000-000000000001'::uuid,'transfer keeps the existing policy template');
SELECT is((SELECT work_policy_version FROM people.work_assignments WHERE tenant_id='f1020000-0000-4000-8000-000000000001' AND employment_id=current_setting('f1.employment')::uuid AND valid_from=current_setting('f1.today')::date),1,'transfer preserves the pinned policy version');
SELECT is((SELECT count(*)::integer FROM people.work_assignments WHERE tenant_id='f1020000-0000-4000-8000-000000000001' AND employment_id=current_setting('f1.employment')::uuid),2,'transfer preserves the prior assignment');
SELECT is((SELECT valid_until FROM people.work_assignments WHERE tenant_id='f1020000-0000-4000-8000-000000000001' AND employment_id=current_setting('f1.employment')::uuid AND valid_from<current_setting('f1.today')::date),current_setting('f1.today')::date,'old context ends at the transfer boundary');
SELECT is((SELECT details->'after'->'context'->>'work_policy_version' FROM people.work_assignment_audit_events WHERE tenant_id='f1020000-0000-4000-8000-000000000001' AND event_key='assignment.transferred'),'1','transfer audit records the preserved policy snapshot');
SET LOCAL ROLE authenticated;
SELECT is(jsonb_array_length(public.attendance_open_day('f1020000-0000-4000-8000-000000000001',current_setting('f1.today')::date,NULL,50)->'items'),1,'attendance opens on the effective transfer day');
SELECT is(jsonb_array_length(public.attendance_open_day('f1020000-0000-4000-8000-000000000001',current_setting('f1.yesterday')::date,NULL,50)->'items'),1,'the pre-transfer attendance day remains available');
SELECT is(public.preview_attendance_csv_import('f1020000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_build_object('employee_code','F1-TRANSFER','site_name','F1 Main','happened_at',current_setting('f1.today')||'T00:01:00+03:00','direction','in','source_event_key','f1-after')))->0->>'status','ready','CSV resolves the transferred employee using inherited policy');
SELECT set_config('f1.future_assignment',(public.schedule_people_work_assignment('f1020000-0000-4000-8000-000000000001',current_setting('f1.employment')::uuid,current_setting('f1.today')::date+1,'f1050000-0000-4000-8000-000000000001',NULL,NULL,NULL)->>'assignment_id'),true);
RESET ROLE;
SELECT is((SELECT work_policy_version FROM people.work_assignments WHERE id=current_setting('f1.future_assignment')::uuid),1,'a subsequent future transfer also preserves the version');
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.cancel_people_work_assignment('f1020000-0000-4000-8000-000000000001',current_setting('f1.employment')::uuid,current_setting('f1.future_assignment')::uuid)$$,'future cancellation remains supported');
SELECT set_config('f1.no_policy',public.create_people_employee('f1020000-0000-4000-8000-000000000001','F1-NONE','Unassigned policy employee','f1040000-0000-4000-8000-000000000001','f1050000-0000-4000-8000-000000000001',current_setting('f1.today')::date-10,'monthly',1000,true)::text,true);
SELECT public.schedule_people_work_assignment('f1020000-0000-4000-8000-000000000001',(current_setting('f1.no_policy')::jsonb->>'employment_id')::uuid,current_setting('f1.today')::date,'f1050000-0000-4000-8000-000000000001',NULL,NULL,NULL);
RESET ROLE;
SELECT ok((SELECT work_policy_template_id IS NULL AND work_policy_version IS NULL FROM people.work_assignments WHERE tenant_id='f1020000-0000-4000-8000-000000000001' AND employment_id=(current_setting('f1.no_policy')::jsonb->>'employment_id')::uuid AND valid_from=current_setting('f1.today')::date),'transfer does not invent a policy for an unassigned employee');
SELECT * FROM finish();
ROLLBACK;